'use strict';
state.spam={policy:{allowed:[],blocked:[]},server:{junkScore:5,rejectScore:15,blocked:[]},messages:[],mailbox:'',error:''};
Object.assign(labels,{overview:'Overview',workspace:'Workspace',mail:'Email',dns:'DNS',security:'Security',spam:'Spam & quarantine'});
labels.php='PHP';
state.php={installed:[],sites:[]};
Object.assign(labels,{sites:'Website WAF',logs:'Site logs'});
labels.adminLogs='Server logs';
labels.admins='Administrators';
state.adminLogSelection={kind:'service',service:'harbor-agent',query:'',page:0};
state.adminLogs={entries:[],page:0,more:false};
state.siteSecurity={sites:[],signatures:[],forcedRateLimit:true};
state.siteLogs={entries:[],page:0,more:false,windowBytes:0};
state.logSelection={hostname:'',kind:'access',query:'',page:0};
state.signatureCatalog=[];
async function loadAdminLogs(){if(isOwner())return;const choice=state.adminLogSelection,base=choice.kind==='updates'?'updates':`admin/logs?kind=${encodeURIComponent(choice.kind)}&service=${encodeURIComponent(choice.service)}`;state.adminLogs=await api(`${base}${base.includes('?')?'&':'?'}q=${encodeURIComponent(choice.query)}&page=${choice.page}`);}
function adminLogsView(){const choice=state.adminLogSelection,logs=state.adminLogs||{entries:[],more:false},tabs=[['service','Services'],['installation','Installation'],['updates','Updates'],['package-output','Package output'],['activity','Activity'],['access','Access'],['error','Errors'],['login','Login']];const units=['harbor-agent','harbor-web','harbor-terminal','harbor-dns','harbor-filter','harbor-signer','harbor-pgadmin','harbor-admin-pgadmin',...state.services.map(row=>row.id)];return `<article class="card"><div class="card-header"><h2>Server logs</h2><button class="button" data-admin-log-export ${logs.entries.length?'':'disabled'}>Export page</button></div><div class="service-tabs">${tabs.map(([kind,label])=>`<button data-admin-log-kind="${kind}" class="${choice.kind===kind?'selected':''}">${label}</button>`).join('')}</div><form id="admin-logs-form" class="section-toolbar">${choice.kind==='service'?`<label>Daemon<select name="service">${units.map(unit=>`<option value="${esc(unit)}" ${choice.service===unit?'selected':''}>${esc(unit)}</option>`).join('')}</select></label>`:''}<label>Search<input name="query" type="search" maxlength="128" value="${esc(choice.query)}" placeholder="Message, package, address…"></label><button class="button primary" type="submit">Search</button></form><div class="table-wrap"><table><thead><tr><th>Latest entries · page ${choice.page+1}</th></tr></thead><tbody>${logs.entries.map(row=>`<tr><td><pre class="site-log-line">${esc(typeof row==='string'?row:choice.kind==='updates'?`${new Date(row.time).toLocaleString()} · ${row.action} ${row.service} · ${row.state} · ${row.message}`:`${new Date(row.time).toLocaleString()} · ${row.unit||''} · ${row.message}`)}</pre></td></tr>`).join('')||emptyRow(1,'No matching entries')}</tbody></table></div><div class="table-footer"><span>${logs.windowBytes?`Search window: ${byte(logs.windowBytes)}`:logs.truncated?'Search limited to latest 20,000 journal entries':''}</span><div class="row-actions"><button class="button small" data-admin-log-page="previous" ${choice.page?'':'disabled'}>Previous</button><button class="button small" data-admin-log-page="next" ${logs.more?'':'disabled'}>Next</button></div></div></article>`;}
document.addEventListener('submit',async event=>{if(event.target.id!=='admin-logs-form')return;event.preventDefault();const data=new FormData(event.target);state.adminLogSelection.query=String(data.get('query')||'');state.adminLogSelection.service=String(data.get('service')||state.adminLogSelection.service);state.adminLogSelection.page=0;try{await loadAdminLogs();renderContent();}catch(error){toast(error.message,true);}});
document.addEventListener('click',async event=>{const kind=event.target.closest('[data-admin-log-kind]'),page=event.target.closest('[data-admin-log-page]');if(kind){state.adminLogSelection.kind=kind.dataset.adminLogKind;state.adminLogSelection.page=0;}else if(page){state.adminLogSelection.page+=page.dataset.adminLogPage==='next'?1:-1;}else if(event.target.closest('[data-admin-log-export]')){const choice=state.adminLogSelection,url=URL.createObjectURL(new Blob([JSON.stringify({selection:choice,entries:state.adminLogs.entries},null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`harbor-${choice.kind}-page-${choice.page+1}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}else return;try{await loadAdminLogs();renderContent();}catch(error){toast(error.message,true);}});
window.addEventListener('hashchange',async()=>{if(state.view==='adminLogs'){try{await loadAdminLogs();if(state.view==='adminLogs')renderContent();}catch(error){toast(error.message,true);}}});
function facts(rows){return rows.map(([name,value])=>`<div class="detail-row"><span>${esc(name)}</span><b>${esc(value)}</b></div>`).join('');}
function emptyRow(columns,label){return `<tr><td colspan="${columns}"><div class="empty">${esc(label)}</div></td></tr>`;}
function renderLogin(error=''){
 disposeTerminal(false);const owner=loginMode==='owner',passwordAdmin=!owner&&state.authMode==='password';
 $('#app').innerHTML=`<div class="login"><aside class="login-aside"><div class="brand"><img src="/mark.svg" alt=""><span>harbor</span></div><h1>Hosting control panel</h1></aside><main class="login-main"><form class="login-form" id="login-form"><h2>Sign in</h2><div class="login-tabs"><button type="button" class="${owner?'selected':''}" data-tenant="login-mode" data-mode="owner">Site owner</button><button type="button" class="${owner?'':'selected'}" data-tenant="login-mode" data-mode="admin">Administrator</button></div>${owner||passwordAdmin?`<label for="username">Username</label><input id="username" autocomplete="username" required maxlength="${owner?16:32}">`:''}<label for="token">${owner||passwordAdmin?'Password':'Administrator token'}</label><div class="password-wrap"><input id="token" type="password" autocomplete="current-password" required maxlength="128"><button class="icon-button" type="button" data-action="reveal" aria-label="Show or hide password">${icon('eye')}</button></div><p class="login-error" role="alert">${esc(error)}</p><button class="button primary" type="submit">Sign in ${icon('arrow')}</button></form></main></div>`;document.title='Harbor · Sign in';
 $('#login-form').addEventListener('submit',async event=>{event.preventDefault();const data=owner?{username:$('#username').value,password:$('#token').value}:passwordAdmin?{kind:'admin',username:$('#username').value,password:$('#token').value}:{kind:'admin',token:$('#token').value};$('button[type=submit]',event.target).disabled=true;try{state.session=await api('login',data);$('#token').value='';state.view=owner?'workspace':canView('overview')?'overview':canView('owners')?'owners':'settings';history.replaceState(null,'','#'+state.view);renderShell();await refresh();}catch(error){if(!owner)await syncAuthMode();renderLogin(error.message);}});
}
function renderShell(){
 const owner=isOwner(),items=(owner?[['workspace','grid'],['sites','shield'],['logs','activity'],['php','code'],['databases','database'],['domains','globe'],['mail','mail'],['spam','shield'],['dns','globe'],['terminal','terminal']]:[['overview','grid'],['services','server'],['updates','refresh'],['adminLogs','activity'],['owners','server'],['sites','shield'],['logs','activity'],['php','code'],['databases','database'],['domains','globe'],['mail','mail'],['spam','shield'],['dns','globe'],['resources','chart'],['activity','activity'],['security','shield'],['settings','settings'],['admins','shield']]).filter(([view])=>canView(view));
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="/mark.svg" alt=""><span>harbor</span></div><div class="workspace"><span class="square">${icon(owner?'server':'shield')}</span><div><b>${owner?esc(state.session.user):'Server'}</b><small>${state.session.role==='impersonated'?'Administrator viewing owner':owner?'Site owner':'Administrator'}</small></div></div><nav class="nav" aria-label="Main navigation">${items.map(([view,image])=>`<button data-view="${view}">${icon(image)}${labels[view]}${view==='services'?'<span class="count" id="nav-service-count">—</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-version"><span>v0.7.1</span><button data-action="logout">Sign out</button></div></div></aside><button class="scrim" data-action="close-menu" aria-label="Close navigation"></button><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb"><b id="breadcrumb-current">${labels[state.view]||'Overview'}</b></div><div class="top-right">${owner||!can('services.read')?'':`<div class="search">${icon('search')}<input id="global-search" placeholder="Find a service…" aria-label="Find a service"></div>`}<button class="profile" data-view="${owner?'workspace':canView('security')?'security':'settings'}"><div class="avatar">${owner?esc(state.session.user.slice(0,2).toUpperCase()):'AD'}</div><div><b>${esc(state.session.user)}</b><small>${state.session.role==='impersonated'?'Administrator viewing owner':owner?'Site owner':'Administrator'}</small></div>${icon('down')}</button></div></header><div class="content" id="content"></div></main>`;
 $('#global-search')?.addEventListener('input',event=>{state.query=event.target.value;state.view='services';history.replaceState(null,'','#services');renderContent();});renderContent();
}
function renderContent(){
 if(!state.session||!$('#content'))return;const allowed=(isOwner()?['workspace','sites','logs','php','databases','domains','mail','spam','dns','terminal']:Object.keys(labels)).filter(canView);if(!allowed.includes(state.view))state.view=isOwner()?'workspace':allowed[0]||'settings';const view=state.view;document.title=`Harbor · ${labels[view]}`;$('#breadcrumb-current').textContent=labels[view];if($('#nav-service-count'))$('#nav-service-count').textContent=installed().length;
 document.querySelectorAll('.nav [data-view]').forEach(button=>{button.classList.toggle('active',button.dataset.view===view);if(button.dataset.view===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
 const content=['owners','workspace','sites','logs','php','databases','domains','mail','spam','dns','terminal'].includes(view)?tenancyView(view):view==='overview'?`${serverStrip()}${metricCards()}<div class="grid-main">${serviceTable(true)}${healthCard()}</div><div class="grid-bottom">${activityCard(true)}${quickCard()}</div>`:view==='services'?`<div class="section-toolbar"><input id="service-search" class="service-search" type="search" aria-label="Search services" placeholder="Search services…" value="${esc(state.query)}"><select id="category" aria-label="Category">${['all','Web','Database','Cache','Runtime','Mail','DNS','Security','System'].map(category=>`<option value="${category}" ${state.category===category?'selected':''}>${category==='all'?'All categories':category}</option>`).join('')}</select></div>${serviceTable()}`:view==='updates'?updatesView():view==='adminLogs'?adminLogsView():view==='resources'?resourcesView():view==='activity'?activityCard():view==='security'?securityView():view==='admins'?adminsView():settingsView();
 $('#content').innerHTML=`${state.session.role==='impersonated'?`<div class="demo-strip"><span>ADMINISTRATOR</span><span>Viewing as ${esc(state.session.user)}</span><button data-tenant="impersonate-stop">Return to administrator</button></div>`:''}${state.session.demo?`<div class="demo-strip"><span>DEMO</span><span>Simulated data</span>${state.session.role==='owner'?'<button data-tenant="preview-admin">Administrator</button>':''}</div>`:''}<div class="title-row"><h1>${labels[view]}</h1><div class="row-actions"><button class="button export-button" data-action="export">${icon('download')}Export</button><button class="button primary" data-action="refresh" ${state.loading?'disabled':''}>${icon('refresh')}Refresh</button></div></div>${state.error?`<div class="connection-error" role="alert">${esc(state.error)}</div>`:''}${content}<footer class="page-footer"><span>Harbor v0.7.1</span><span>${state.lastUpdated?state.lastUpdated.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}):''}</span></footer>`;
 $('#service-search')?.addEventListener('input',event=>{const position=event.target.selectionStart;state.query=event.target.value;renderContent();$('#service-search').focus();$('#service-search').setSelectionRange(position,position);});$('#category')?.addEventListener('change',event=>{state.category=event.target.value;renderContent();});
}
function servicePrimary(service){const action=service.load==='loaded'?(service.status==='active'?'restart':'start'):'install',job=state.jobs?.[service.id];const busy=job&&['queued','running'].includes(job.state);const disabled=!can('services.manage')||state.pending||busy||service.load!=='loaded'&&!service.installable||service.id==='postgresql'&&service.status==='active';return `<button class="button small" data-control="${action}" data-service="${esc(service.id)}" ${disabled?'disabled':''}>${busy?job.state==='queued'?'Queued':'Working…':titleCase(action)}</button>`;}
function serviceTable(compact=false){let rows=state.services.filter(service=>state.filter==='all'||(state.filter==='available'?service.load!=='loaded':service.load==='loaded'));if(!compact&&state.category!=='all')rows=rows.filter(service=>service.category===state.category);if(!compact&&state.query)rows=rows.filter(service=>`${service.name} ${service.id}`.toLowerCase().includes(state.query.toLowerCase()));if(compact)rows=installed().slice(0,6);return `<article class="card"><div class="card-header"><h2>Services</h2>${compact?'<button class="text-link" data-view="services">View all</button>':''}</div>${compact?'':`<div class="service-tabs">${[['installed','Installed'],['available','Not installed'],['all','All']].map(([filter,label])=>`<button data-filter="${filter}" class="${state.filter===filter?'selected':''}">${label}</button>`).join('')}</div>`}<div class="table-wrap"><table><thead><tr><th>Service</th><th>Status</th><th class="memory-col">Memory</th><th>Actions</th></tr></thead><tbody>${rows.map(service=>`<tr><td><div class="service-identity">${serviceLogo(service)}<div><b>${esc(service.name)}</b><small>${esc(service.category)}</small></div></div></td><td><span class="status-pill ${esc(service.load==='loaded'?service.status:'inactive')}"><span class="dot"></span>${['queued','running','failed'].includes(state.jobs?.[service.id]?.state)?esc(state.jobs[service.id].action+' '+state.jobs[service.id].state):service.load==='loaded'?esc(statusLabel(service)):service.load==='masked'?'Masked':'Not installed'}</span></td><td class="memory-col">${service.memory?byte(service.memory):'—'}</td><td><div class="service-action">${servicePrimary(service)}<button class="icon-button" data-detail="${esc(service.id)}" aria-label="${esc(service.name)} details">${icon('dots')}</button></div></td></tr>`).join('')||emptyRow(4,state.loading?'Loading…':'No services')}</tbody></table></div><div class="table-footer"><span>${rows.length} services</span></div></article>`;}
function healthCard(){const total=installed().length,active=running().length,percent=total?Math.round(active*100/total):0;return `<article class="card health"><div class="card-header"><h2>Service status</h2></div><div class="health-ring"><svg viewBox="0 0 148 148" aria-hidden="true"><circle class="ring-track" cx="74" cy="74" r="58"/><circle class="ring-value" cx="74" cy="74" r="58" stroke-dashoffset="${365*(1-percent/100)}"/></svg><div class="ring-center"><b>${total?percent:'—'}<small>%</small></b><span>running</span></div></div><div class="health-facts">${facts([['Running',active],['Stopped / failed',total-active]])}</div></article>`;}
function quickCard(){return `<article class="card quick-card"><div class="card-header"><h2>Quick access</h2></div><div class="quick-actions">${[['owners','server'],['mail','mail'],['spam','shield'],['dns','globe']].filter(([view])=>canView(view)).map(([view,image])=>`<button class="quick-action" data-view="${view}"><span class="quick-icon">${icon(image)}</span><b>${labels[view]}</b>${icon('chevron')}</button>`).join('')}</div></article>`;}
function resourcesView(){return `${metricCards()}<div class="detail-grid">${[['cpu','CPU'],['memory','Memory']].map(([metric,label])=>`<article class="card detail-card"><h2>${label}</h2><div class="chart-large">${spark(metric,'#a493df',true)}</div></article>`).join('')}<article class="card detail-card"><h2>Host</h2>${facts([['Hostname',state.metrics?.hostname||'—'],['Uptime',state.metrics?`${Math.floor(state.metrics.uptime/86400)} days`:'—'],['Load average',state.metrics?.load?.toFixed(2)||'—']])}</article></div>`;}
function securityView(){const fail2ban=state.services.find(service=>service.id==='fail2ban');const waf=state.waf||{installed:false,mode:'off'};return `<div class="detail-grid"><article class="card detail-card"><h2>Session</h2>${facts([['Account',state.session.user],['Role','Administrator'],['Expires','1 hour'],['Cookie','Secure · HttpOnly · SameSite'],['Request validation','Origin + CSRF']])}</article><article class="card detail-card"><h2>Login protection</h2>${facts([['Per address','5 failures / minute'],['Per account','10 failures / 5 minutes'],['Fail2ban',fail2ban?.load==='loaded'?statusLabel(fail2ban):'Not installed']])}</article><article class="card detail-card"><h2>Website WAF</h2>${facts([['Mode',waf.installed?titleCase(waf.mode):'Not installed'],['Site include',waf.siteInclude||'—']])}<div class="dialog-actions">${(waf.installed?['off','detection','blocking']:['install']).map(mode=>`<button class="button ${mode==='blocking'?'danger':''}" data-waf="${mode}" ${!can('security.manage')||state.pending||mode===waf.mode?'disabled':''}>${titleCase(mode)}</button>`).join('')}</div><div class="dialog-actions"><button class="button primary" data-view="sites">Configure site rules and bot protection</button><button class="button" data-view="logs">View site logs</button></div></article><article class="card detail-card"><h2>Access</h2><div class="dialog-actions"><button class="button" data-view="owners">Site owners</button><button class="button" data-action="logout">Sign out</button></div></article></div>`;}
function settingsView(){return `<div class="detail-grid"><article class="card detail-card"><h2>Server</h2>${facts([['Panel','Harbor'],['Version',state.release?.installedTag||'Source build'],['Hostname',state.metrics?.hostname||'—'],['Platform','Ubuntu 24.04 LTS'],['Origin',state.session.origin||location.origin]])}</article><article class="card detail-card"><h2>Reports</h2><button class="button" data-action="export">${icon('download')}Export</button>${canView('updates')?'<button class="button" data-view="updates">Panel updates</button>':''}</article></div>`;}
function showDetails(id){const service=state.services.find(row=>row.id===id);if(!service)return;const packageAction=service.load==='loaded'&&service.removable?'remove':service.load!=='loaded'&&service.installable?'install':'';showDialog(`<h2 id="dialog-title">${esc(service.name)}</h2>${facts([['Unit',service.id+'.service'],['Status',service.load==='loaded'?statusLabel(service):'Not installed'],['Memory',service.memory?byte(service.memory):'—'],['Default service',service.default?'Yes':'No']])}<div class="dialog-actions">${['start','reload','restart','stop'].map(action=>`<button class="button ${action==='stop'?'danger':''}" data-control="${action}" data-service="${esc(service.id)}" ${!can('services.manage')||service.load!=='loaded'||state.pending||service.id==='postgresql'&&action!=='start'?'disabled':''}>${titleCase(action)}</button>`).join('')}${packageAction?`<button class="button ${packageAction==='remove'?'danger':''}" data-control="${packageAction}" data-service="${esc(service.id)}" ${!can('services.manage')||state.pending?'disabled':''}>${titleCase(packageAction)}</button>`:''}</div>`);}
function adminDatabaseTools(){const tools=state.tools||{};return `<article class="card detail-card"><h2>Administrator database access</h2><div class="dialog-actions"><button class="button primary" data-admin-db-tool="mariadb" ${tools.configured?'':'disabled'}>phpMyAdmin · all databases</button><button class="button" data-admin-db-tool="postgresql" ${tools.configured?'':'disabled'}>pgAdmin · all databases</button></div></article>`;}
function tenancyView(view){
 const owner=selectedOwner(),profile=state.session.profile||{};
 if(view==='owners')return `<article class="card"><div class="card-header"><h2>Site owners</h2><button class="button primary" data-tenant="create-owner">Create owner</button></div><div class="table-wrap"><table><thead><tr><th>Owner</th><th>Database prefix</th><th>Shell</th><th>Actions</th></tr></thead><tbody>${ownerRows()||emptyRow(4,'No owners')}</tbody></table></div></article>`;
 if(view==='workspace')return `<div class="detail-grid"><article class="card detail-card"><h2>${esc(owner)}</h2>${facts([['UID',profile.uid??'—'],['Home',profile.home||'—'],['Shell',profile.terminalEnabled?profile.shell:'Disabled'],['Database prefix',profile.prefix+'*']])}</article><article class="card detail-card"><h2>Services</h2><div class="workspace-links">${[['sites','shield'],['logs','activity'],['php','code'],['databases','database'],['domains','globe'],['mail','mail'],['spam','shield'],['dns','globe'],['terminal','terminal']].map(([target,image])=>`<button class="button" data-view="${target}" ${target==='terminal'&&!profile.terminalEnabled?'disabled':''}>${icon(image)}${labels[target]}</button>`).join('')}</div></article></div>`;
 if(!owner)return `${view==='databases'&&!isOwner()?adminDatabaseTools():''}${ownerPicker()}<div class="card empty">No site owner selected</div>`;
 if(view==='sites')return siteSecurityView()+tlsView();if(view==='logs')return siteLogsView();if(view==='php')return phpView()+(!isOwner()?phpExtensionsView():'');if(view==='mail')return mailView();if(view==='spam')return spamView();if(view==='dns'){if(!state.domains.owned.some(row=>row.name===state.dns.domain))state.dns={domain:state.domains.owned[0]?.name||'',connected:false,records:[],page:1,pages:1};return dnsView();}
 if(view==='databases')return `${!isOwner()?adminDatabaseTools():''}${ownerPicker()}<div class="detail-grid tools-grid">${[['mariadb','MariaDB','phpMyAdmin'],['postgresql','PostgreSQL','pgAdmin']].map(([engine,label,tool])=>`<article class="card detail-card"><h2>${label}</h2><div class="dialog-actions"><button class="button primary" data-tenant="create-db" data-engine="${engine}" data-kind="database">Create database</button><button class="button" data-tenant="create-db" data-engine="${engine}" data-kind="user">Create user</button>${isOwner()?`<button class="button" data-db-tool="${engine}" ${!state.tools.configured&&!state.session.demo?'disabled':''}>${tool}</button>`:""}</div></article>`).join('')}</div><article class="card"><div class="card-header"><h2>${esc(owner)}_*</h2></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Engine</th><th>Type</th></tr></thead><tbody>${[...state.database.databases.map(row=>({...row,kind:'Database'})),...state.database.users.map(row=>({...row,kind:'User'}))].map(row=>`<tr><td>${esc(row.name)}</td><td>${row.engine==='mariadb'?'MariaDB':'PostgreSQL'}</td><td>${row.kind}</td></tr>`).join('')||emptyRow(3,'No databases or users')}</tbody></table></div></article>`;
 if(view==='domains')return `${ownerPicker()}<article class="card"><div class="card-header"><h2>Primary domains</h2><div class="row-actions">${!isOwner()?'<button class="button" data-tenant="assign-domain">Assign domain</button>':''}<button class="button primary" data-tenant="delegate" ${state.domains.owned.length?'':'disabled'}>Delegate subdomain</button></div></div>${state.domains.owned.map(domain=>`<div class="zone-heading">${icon('globe')}<b>${esc(domain.name)}</b></div><div class="table-wrap"><table><thead><tr><th>Subdomain</th><th>Owner</th><th>Actions</th></tr></thead><tbody>${domain.delegations.map(grant=>`<tr><td>${esc(grant.label+'.'+domain.name)}</td><td>${esc(grant.target)}</td><td><button class="button small" data-tenant="revoke" data-domain="${esc(domain.name)}" data-label="${esc(grant.label)}">Revoke</button></td></tr>`).join('')||emptyRow(3,'No delegations')}</tbody></table></div>`).join('')||'<div class="empty">No primary domains</div>'}</article><article class="card tenant-resources"><div class="card-header"><h2>Delegated domains</h2></div><div class="table-wrap"><table><thead><tr><th>Hostname</th><th>Primary owner</th></tr></thead><tbody>${state.domains.delegated.map(row=>`<tr><td>${esc(row.hostname)}</td><td>${esc(row.domainOwner)}</td></tr>`).join('')||emptyRow(2,'No delegated domains')}</tbody></table></div></article>`;
 if(view==='terminal')return `<article class="card terminal-card"><div class="card-header"><div><h2>${esc(owner)}</h2><span class="muted">${profile.terminalEnabled?esc(profile.shell):'Shell disabled'}</span></div><div class="row-actions"><button class="button primary" data-tenant="terminal-open" ${profile.terminalEnabled?'':'disabled'}>Connect</button><button class="button" data-tenant="terminal-close">Disconnect</button></div></div><div id="terminal-screen"><div class="terminal-placeholder">${icon('terminal')}${profile.terminalEnabled?'Disconnected':'Shell disabled'}</div></div></article>`;return '';
}
async function loadTenant(){
 const owner=selectedOwner(),allowed=permission=>can(permission);
 const safe=async(permission,endpoint,fallback)=>allowed(permission)?api(endpoint):fallback;
 state.tools=await safe('database_tools','tools',{configured:false});
 if(!owner){state.database={databases:[],users:[]};state.domains={owned:[],delegated:[]};state.php={installed:[],sites:[]};state.siteSecurity={sites:[],signatures:[],forcedRateLimit:true};state.tls={sites:[],configured:false};state.siteLogs={entries:[],page:0,more:false,windowBytes:0};state.mail={enabled:false,configured:false,mailboxes:[],domains:[],security:[]};return;}
 const query=`owner=${encodeURIComponent(owner)}`;
 const [database,domains,targets,mail,php,siteSecurity,tls]=await Promise.all([
  safe('databases.read',`databases?${query}`,{databases:[],users:[]}),
  safe('domains.read',`domains?${query}`,{owned:[],delegated:[]}),
  safe('domains.read','delegation-targets',[]),
  safe('mail.read',`mail?${query}`,{enabled:false,configured:false,mailboxes:[],domains:[],security:[]}),
  safe('php.read',`php/versions?${query}`,{installed:[],sites:[]}),
  safe('sites.read',`site/security?${query}`,{sites:[],signatures:[],forcedRateLimit:true}),
  safe('sites.read',`tls?${query}`,{sites:[],configured:false})
 ]);
 if(!state.session||selectedOwner()!==owner)return;
 Object.assign(state,{database,domains,targets,mail,php,siteSecurity,tls});
 if(!isOwner()&&can('security.read'))state.signatureCatalog=(await api('site/signatures')).signatures;
 if(!siteSecurity.sites.some(site=>site.hostname===state.logSelection.hostname))state.logSelection={hostname:siteSecurity.sites[0]?.hostname||'',kind:'access',query:'',page:0};
 if(state.view==='logs'&&allowed('sites.read'))await loadSiteLogs();
 if(state.view==='dns'&&allowed('dns.read'))await loadDNS();
 if(state.view==='spam'&&allowed('spam.read'))await loadSpam();
}
function siteSecurityView(){const policy=state.siteSecurity||{sites:[],signatures:[]};return `${ownerPicker()}${isOwner()?'':`<article class="card detail-card"><h2>Add signature</h2><form id="site-signature-form"><div class="detail-grid"><label>Name<input name="name" required minlength="2" maxlength="40" pattern="[A-Za-z0-9 _-]{2,40}"></label><label>Match in<select name="target"><option value="path">Request URL</option><option value="user_agent">User agent</option></select></label><label>Literal text<input name="needle" required minlength="2" maxlength="80" pattern="[a-z0-9._/-]{2,80}" placeholder="example-bot/"></label><label>Action<select name="action"><option value="block">Block</option><option value="detect">Log only</option></select></label></div><label><input type="checkbox" name="forced"> Required on every protected site</label><div class="dialog-actions"><button class="button primary" type="submit">Add signature</button></div></form></article>`}${isOwner()?'':signatureCatalogView()}<article class="card detail-card"><h2>Required protection</h2>${facts([['Request flood limit','10 requests/second per IP, burst 40'],['Owner control','Always on when the site include is active'],['Signature enforcement',policy.mode==='blocking'?'Blocking':policy.mode==='detection'?'Detection only':'Off']])}</article>${policy.sites.map(site=>`<article class="card detail-card"><div class="card-header"><h2>${esc(site.hostname)}</h2><span class="status-pill ${site.configured?'active':'inactive'}">${site.configured?'Policy ready':'Needs setup'}</span></div><form data-site-security-form="${esc(site.hostname)}"><label><input type="checkbox" name="bot" ${site.bot?'checked':''}> Block missing and common scripted user agents</label><div class="workspace-links">${policy.signatures.map(signature=>`<label><input type="checkbox" name="signature" value="${signature.id}" ${signature.forced||site.signatures.includes(signature.id)?'checked':''} ${signature.forced?'disabled':''}> ${esc(signature.name)} · ${signature.action==='detect'?'Log only':'Block'}${signature.forced?' · Required':''}</label>`).join('')||'<span class="muted">No custom signatures</span>'}</div><div class="dialog-actions"><button class="button primary" type="submit">Save site protection</button><button class="button" type="button" data-view="logs">View logs</button></div></form></article>`).join('')||'<div class="card empty">No websites allocated</div>'}`;}
function tlsView(){const tls=state.tls||{sites:[],configured:false};return `<article class="card"><div class="card-header"><h2>Website SSL certificates</h2><span class="muted">Let's Encrypt · HTTP verification</span></div><p class="muted">Point each hostname to this server and allow inbound port 80 before requesting a certificate. Renewals run automatically.</p>${!tls.configured?'<p class="connection-error">An administrator must set a Let’s Encrypt contact email before requests are available.</p>':''}${!isOwner()&&can('security.manage')?'<form id="tls-contact-form" class="section-toolbar"><label>Let’s Encrypt contact email<input name="email" type="email" required maxlength="254" autocomplete="email"></label><button class="button" type="submit">Save contact email</button></form>':''}<div class="table-wrap"><table><thead><tr><th>Website</th><th>Certificate</th><th>Action</th></tr></thead><tbody>${tls.sites.map(site=>`<tr><td>${esc(site.hostname)}</td><td>${esc(site.state)}${site.detail?`<small class="cell-subtitle">${esc(site.detail)}</small>`:''}</td><td><button class="button small" data-tls-issue="${esc(site.hostname)}" ${tls.configured&&site.state!=='running'&&can('sites.manage')?'':'disabled'}>${site.state==='active'?'Renew / check':'Request certificate'}</button></td></tr>`).join('')||emptyRow(3,'No websites allocated')}</tbody></table></div></article>`;}
function signatureCatalogView(){return `<article class="card"><div class="card-header"><h2>Signature catalog</h2></div><div class="table-wrap"><table><thead><tr><th>Signature</th><th>Match</th><th>Policy</th><th>Action</th></tr></thead><tbody>${state.signatureCatalog.map(row=>`<tr><td>${esc(row.name)} <small>#${row.id}</small></td><td>${esc(row.target)} · ${esc(row.needle)}</td><td>${row.forced?'Required':'Optional'} · ${row.action==='detect'?'Log only':'Block'}</td><td><button class="button small" data-signature-status="${row.id}" data-enabled="${!row.enabled}">${row.enabled?'Pause':'Enable'}</button></td></tr>`).join('')||emptyRow(4,'No signatures')}</tbody></table></div></article>`;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-tls-issue]');if(!button||button.disabled)return;button.disabled=true;try{await api('tls/issue',{owner:selectedOwner(),hostname:button.dataset.tlsIssue});state.tls=await api(`tls?owner=${encodeURIComponent(selectedOwner())}`);renderContent();toast('Certificate request queued. Refresh to see the result.');}catch(error){toast(error.message,true);button.disabled=false;}});
document.addEventListener('submit',async event=>{if(event.target.id!=='tls-contact-form')return;event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;try{await api('tls/contact',{email:new FormData(form).get('email')});state.tls=await api(`tls?owner=${encodeURIComponent(selectedOwner())}`);renderContent();toast('Certificate contact email saved.');}catch(error){toast(error.message,true);button.disabled=false;}});
function logEntry(line,kind){if(kind==='access'){try{const entry=JSON.parse(line);return `<div><b>${esc(entry.time)}</b> · ${esc(entry.ip)} · ${esc(entry.method)} ${esc(entry.path)} · ${esc(entry.status)}${entry.rate&&entry.rate!=='-'?` · Rate ${esc(entry.rate)}`:''}</div>`;}catch{}}if(kind==='waf'){try{const entry=JSON.parse(line);return `<div><b>${esc(entry.time)}</b> · ${esc(entry.ip)} · ${esc(entry.path)} · HTTP ${esc(entry.status)}<div class="muted">${(entry.messages||[]).map(message=>`Rule ${esc(message.id)}: ${esc(message.message)}`).join(' · ')}</div></div>`;}catch{}}return `<pre class="site-log-line">${esc(line)}</pre>`;}
function siteLogsView(){const sites=state.siteSecurity?.sites||[],selection=state.logSelection,logs=state.siteLogs||{entries:[],page:0,more:false,windowBytes:0};return `${ownerPicker()}<article class="card"><div class="card-header"><h2>Search site logs</h2><button class="button" data-site-log-export ${logs.entries.length?'':'disabled'}>Export page</button></div><form id="site-logs-form" class="section-toolbar"><label>Website<select name="hostname">${sites.map(site=>`<option value="${esc(site.hostname)}" ${site.hostname===selection.hostname?'selected':''}>${esc(site.hostname)}</option>`).join('')}</select></label><label>Log<select name="kind">${[['access','Access'],['error','Errors'],['php','PHP errors'],['waf','WAF actions']].map(([value,label])=>`<option value="${value}" ${value===selection.kind?'selected':''}>${label}</option>`).join('')}</select></label><label>Search<input name="query" type="search" maxlength="128" value="${esc(selection.query)}" placeholder="IP, path, rule ID…"></label><button class="button primary" type="submit" ${sites.length?'':'disabled'}>Search</button></form><div class="table-wrap"><table><thead><tr><th>Latest matches · page ${selection.page+1}</th></tr></thead><tbody>${logs.entries.map(line=>`<tr><td>${logEntry(line,selection.kind)}</td></tr>`).join('')||emptyRow(1,sites.length?'No matching entries':'No websites allocated')}</tbody></table></div><div class="table-footer"><span>Search window: ${byte(logs.windowBytes||0)}</span><div class="row-actions"><button class="button small" data-site-log-page="previous" ${selection.page?'':'disabled'}>Previous</button><button class="button small" data-site-log-page="next" ${logs.more?'':'disabled'}>Next</button></div></div></article>`;}
async function loadSiteLogs(){const selection=state.logSelection;if(!selection.hostname){state.siteLogs={entries:[],page:0,more:false,windowBytes:0};return;}state.siteLogs=await api(`site/logs?owner=${encodeURIComponent(selectedOwner())}&hostname=${encodeURIComponent(selection.hostname)}&kind=${selection.kind}&q=${encodeURIComponent(selection.query)}&page=${selection.page}`);}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id==='site-signature-form'){event.preventDefault();const data=new FormData(form);try{await api('site/signatures',{name:data.get('name'),target:data.get('target'),needle:data.get('needle'),action:data.get('action'),forced:data.has('forced')});await loadTenant();renderContent();toast('Signature added.');}catch(error){toast(error.message,true);}return;}if(form.matches('[data-site-security-form]')){event.preventDefault();const data=new FormData(form);try{state.siteSecurity=await api('site/security',{owner:selectedOwner(),hostname:form.dataset.siteSecurityForm,bot:data.has('bot'),signatures:data.getAll('signature').map(Number)});renderContent();toast('Site protection saved.');}catch(error){toast(error.message,true);}return;}if(form.id==='site-logs-form'){event.preventDefault();const data=new FormData(form);state.logSelection={hostname:String(data.get('hostname')),kind:String(data.get('kind')),query:String(data.get('query')),page:0};try{await loadSiteLogs();renderContent();}catch(error){toast(error.message,true);}}});
document.addEventListener('click',async event=>{const signature=event.target.closest('[data-signature-status]');if(signature){try{await api('site/signatures/status',{id:Number(signature.dataset.signatureStatus),enabled:signature.dataset.enabled==='true'});await loadTenant();renderContent();toast('Signature status saved.');}catch(error){toast(error.message,true);}return;}const page=event.target.closest('[data-site-log-page]');if(page){state.logSelection.page+=page.dataset.siteLogPage==='next'?1:-1;try{await loadSiteLogs();renderContent();}catch(error){toast(error.message,true);}return;}if(event.target.closest('[data-site-log-export]')){const selection=state.logSelection,content=JSON.stringify({website:selection.hostname,log:selection.kind,query:selection.query,page:selection.page+1,entries:state.siteLogs.entries},null,2),url=URL.createObjectURL(new Blob([content],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`${selection.hostname}-${selection.kind}-page-${selection.page+1}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
function phpView(){const runtime=state.php||{installed:[],sites:[]};return `${ownerPicker()}${isOwner()?'':`<article class="card detail-card"><h2>Installed PHP runtimes</h2><p class="muted">PHP 8.3 uses Ubuntu packages. Installing another version explicitly adds the signed ondrej/php PPA.</p><div class="workspace-links">${['8.1','8.2','8.3','8.4','8.5'].map(version=>{const service=state.services.find(item=>item.id===`php${version}-fpm`),job=state.jobs?.[service?.id];return `<div><b>PHP ${version}</b> <span class="muted">${runtime.installed.includes(version)?'Installed':job?.state==='failed'?'Install failed':job?.state==='queued'?'Queued':job?.state==='running'?'Installing…':'Not installed'}</span> ${service&&!runtime.installed.includes(version)?`<button class="button small" data-control="install" data-service="${service.id}" ${state.pending||['queued','running'].includes(job?.state)||!service.installable?'disabled':''}>Install</button>`:''} ${job?.state==='failed'?'<button class="button small" data-update-log>View failure</button>':''}</div>`;}).join('')}</div></article>`}<article class="card"><div class="card-header"><h2>Website PHP versions</h2><span class="muted">${runtime.installed.length?`Available: ${runtime.installed.map(v=>'PHP '+v).join(', ')}`:'No PHP-FPM versions installed'}</span></div><div class="table-wrap"><table><thead><tr><th>Website</th><th>Current</th><th>Version</th><th>Action</th></tr></thead><tbody>${runtime.sites.map(site=>`<tr><td><b>${esc(site.hostname)}</b></td><td>${site.selected?`PHP ${esc(site.selected)}${site.ready?'':' · Pool offline'}`:'Not selected'}</td><td><select data-php-version="${esc(site.hostname)}" aria-label="PHP version for ${esc(site.hostname)}" ${runtime.installed.length?'':'disabled'}><option value="">Choose version</option>${runtime.installed.map(version=>`<option value="${esc(version)}" ${site.selected===version?'selected':''}>PHP ${esc(version)}</option>`).join('')}</select></td><td><button class="button small" data-php-save="${esc(site.hostname)}" ${runtime.installed.length&&!state.pending?'':'disabled'}>Save</button></td></tr>`).join('')||emptyRow(4,'No websites allocated')}</tbody></table></div></article>`;}
function phpExtensionsView(){return `<article class="card"><div class="card-header"><h2>PHP extensions</h2><span class="muted">Choose modules for each installed version</span></div>${(state.phpExtensions?.versions||[]).filter(row=>row.installed).map(row=>`<div class="zone-heading"><b>PHP ${esc(row.version)}</b></div><div class="workspace-links">${row.extensions.map(extension=>{const job=state.jobs?.[extension.package],busy=['queued','running'].includes(job?.state);return `<div class="detail-row"><span>${esc(extension.name)} ${extension.required?'· Required':''}</span><span>${job?.state==='failed'?'Failed':busy?titleCase(job.state):extension.installed?'Installed':'Available'} <button class="button small" data-php-package="${esc(extension.package)}" data-php-action="${extension.installed?'remove':'install'}" ${state.pending||busy||extension.required&&extension.installed?'disabled':''}>${extension.installed?'Remove':'Install'}</button></span></div>`;}).join('')}</div>`).join('')||'<div class="empty">Install a PHP version to manage its extensions.</div>'}</article>`;}
document.addEventListener('click',async event=>{if(event.target.closest('[data-update-log]')){state.adminLogSelection={kind:'updates',service:'harbor-agent',query:'',page:0};navigate('adminLogs');await loadAdminLogs();renderContent();return;}const button=event.target.closest('[data-php-package]');if(!button||button.disabled)return;button.disabled=true;try{const result=await api('package',{service:button.dataset.phpPackage,action:button.dataset.phpAction});toast(result.message||'Package operation queued.');await refresh();}catch(error){toast(error.message,true);button.disabled=false;}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-php-save]');if(!button||button.disabled)return;const hostname=button.dataset.phpSave,version=[...document.querySelectorAll('[data-php-version]')].find(field=>field.dataset.phpVersion===hostname)?.value;if(!version){toast('Choose a PHP version.',true);return;}button.disabled=true;try{state.php=await api('php/select',{owner:selectedOwner(),hostname,version});renderContent();toast(`PHP ${version} selected for ${hostname}.`);}catch(error){toast(error.message,true);button.disabled=false;}});
function mailView(){const mail=state.mail;return `${ownerPicker()}<article class="card mail-choice"><div class="mail-choice-icon">${icon('mail')}</div><div><h2>Email hosting</h2><span class="status-pill ${mail.enabled?'active':'inactive'}">${mail.enabled?'Enabled':'Disabled'}</span>${!mail.configured?'<span class="muted">Not configured</span>':''}</div><button class="button ${mail.enabled?'':'primary'}" data-hosting="mail-choice" ${mail.configured?'':'disabled'}>${mail.enabled?'Disable':'Enable'}</button></article>${mail.applied===false?`<div class="connection-error" role="alert">Configuration pending${!isOwner()?'<button class="button small" data-hosting="mail-apply">Retry</button>':''}</div>`:''}<div class="detail-grid"><article class="card detail-card"><h2>Connection</h2>${facts([['Default mailbox',mail.defaultMailbox||'—'],['Alias',mail.mainDomain?'webmaster@'+mail.mainDomain:'—'],['Server',mail.hostname||'—'],['IMAP','993 · TLS'],['SMTP','465 · TLS / 587 · STARTTLS'],['Username','Email address']])}</article><article class="card detail-card"><h2>Mailboxes</h2><div class="dialog-actions"><button class="button" data-db-tool="roundcube" ${!mail.enabled||(!state.tools.webmailConfigured&&!state.session.demo)?'disabled':''}>Roundcube</button><button class="button" data-view="spam">Spam & quarantine</button><button class="button" data-mail-primary>Main domain</button></div>${facts([['Used',`${mail.mailboxes?.length||0} / 100`]])}<div class="dialog-actions"><button class="button primary" data-hosting="mail-create" ${mail.enabled&&mail.configured&&mail.domains?.length?'':'disabled'}>Create mailbox</button></div></article></div><article class="card tenant-resources"><div class="card-header"><h2>Domains</h2></div><div class="table-wrap"><table><thead><tr><th>Domain</th><th>DKIM</th><th>Autodiscovery</th><th>Actions</th></tr></thead><tbody>${(mail.security||[]).map(domain=>`<tr><td><b>${esc(domain.domain)}</b><small class="cell-subtitle">${esc(domain.activeSelector||domain.pendingSelector||'')}</small></td><td><span class="status-pill ${mail.enabled&&domain.dkimEnabled?'active':'inactive'}">${!mail.enabled?'Hosting disabled':domain.dkimEnabled?'Enabled':domain.pendingSelector?'Key ready':'Disabled'}</span></td><td><button class="button small" data-mail-security="discovery" data-domain="${esc(domain.domain)}" ${mail.enabled?'':'disabled'}>${domain.discoveryEnabled?'Disable':'Enable'}</button></td><td><div class="row-actions"><button class="button small" data-mail-security="generate" data-domain="${esc(domain.domain)}" ${mail.enabled?'':'disabled'}>${domain.activeSelector?'Rotate key':'Generate key'}</button>${domain.pendingSelector||!domain.dkimEnabled&&Object.keys(domain.selectors||{}).length?`<button class="button small" data-mail-security="activate" data-domain="${esc(domain.domain)}" ${mail.enabled?'':'disabled'}>Activate</button>`:''}${domain.dkimEnabled?`<button class="button small" data-mail-security="disable" data-domain="${esc(domain.domain)}" ${mail.enabled?'':'disabled'}>Disable DKIM</button>`:''}<button class="button small" data-mail-security="records" data-domain="${esc(domain.domain)}">DNS records</button></div></td></tr>`).join('')||emptyRow(4,'No primary domains')}</tbody></table></div></article><article class="card tenant-resources"><div class="card-header"><h2>Mailboxes</h2></div><div class="table-wrap"><table><thead><tr><th>Address</th><th>Status</th><th>Actions</th></tr></thead><tbody>${(mail.mailboxes||[]).map(box=>`<tr><td>${esc(box.address)}</td><td><span class="status-pill ${mail.enabled&&box.enabled?'active':'inactive'}">${mail.enabled&&box.enabled?'Enabled':'Disabled'}</span></td><td><div class="row-actions"><button class="button small" data-hosting="mail-password" data-domain="${esc(box.domain)}" data-local="${esc(box.local)}">Password</button><button class="button small" data-hosting="mail-toggle" data-domain="${esc(box.domain)}" data-local="${esc(box.local)}" data-enabled="${!box.enabled}">${box.enabled?'Disable':'Enable'}</button></div></td></tr>`).join('')||emptyRow(3,'No mailboxes')}</tbody></table></div></article>`;}
function domainMail(domain){return (state.mail.security||[]).find(row=>row.domain===domain);}
function dnsRecordValue(record){return record.type==='SRV'?`${record.data.priority} ${record.data.weight} ${record.data.port} ${record.data.target}`:record.type==='MX'?`${record.priority??10} ${record.content}`:record.content;}
function dnsZoneRecord(record){let value=dnsRecordValue(record);if(record.type==='TXT')value=(record.content.match(/.{1,200}/g)||['']).map(chunk=>'"'+chunk.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"').join(' ');else if(['MX','CNAME','SRV'].includes(record.type))value+='.';return `${record.name}.\t${record.ttl}\tIN\t${record.type}\t${value}`;}
function mailRecordTable(domain){return `<div class="table-wrap"><table><thead><tr><th>Type</th><th>Name</th><th>Value</th><th>Actions</th></tr></thead><tbody>${(domain?.records||[]).map((record,index)=>`<tr><td><span class="record-type">${esc(record.type)}</span></td><td>${esc(record.name)}</td><td class="dns-value">${esc(dnsRecordValue(record))}</td><td><div class="row-actions"><button class="button small" data-mail-record="copy" data-domain="${esc(domain.domain)}" data-index="${index}">Copy</button>${domain.provider==='cloudflare'?`<button class="button small" data-mail-record="publish" data-domain="${esc(domain.domain)}" data-index="${index}">Publish</button>`:''}</div></td></tr>`).join('')||emptyRow(4,'No records')}</tbody></table></div>`;}
function dnsView(){const dns=state.dns,allocation=state.domains.owned.find(row=>row.name===dns.domain),provider=allocation?.dnsProvider||'external';return `${ownerPicker()}<div class="section-toolbar"><label for="dns-domain">Domain</label><select id="dns-domain">${state.domains.owned.map(row=>`<option ${row.name===dns.domain?'selected':''}>${esc(row.name)}</option>`).join('')}</select><label for="dns-provider">DNS provider</label><select id="dns-provider" ${dns.domain?'':'disabled'}><option value="external" ${provider==='external'?'selected':''}>External DNS</option><option value="cloudflare" ${provider==='cloudflare'?'selected':''}>Cloudflare</option></select>${dnsLoading?'<span class="muted">Loading…</span>':''}</div>${dns.error?`<div class="connection-error" role="alert">${esc(dns.error)}</div>`:''}${!dns.domain?'<div class="card empty">No primary domains</div>':provider==='external'?`<article class="card"><div class="card-header"><h2>Mail DNS records</h2></div>${state.mail.enabled?mailRecordTable(domainMail(dns.domain)):'<div class="empty">No local mail records</div>'}</article>`:!dns.connected?`<article class="card detail-card"><h2>Cloudflare</h2>${facts([['Domain',dns.domain],['Status','Disconnected']])}<div class="dialog-actions"><button class="button primary" data-hosting="dns-connect">Connect</button></div></article>`:`<article class="card"><div class="card-header"><h2>Cloudflare DNS</h2><div class="row-actions"><button class="button small" data-hosting="dns-connect">API token</button><button class="button primary" data-hosting="dns-create">Add record</button></div></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Name</th><th>Content</th><th>Proxy</th><th>Actions</th></tr></thead><tbody>${dns.records.map(record=>`<tr><td><span class="record-type">${esc(record.type)}</span></td><td>${esc(record.name)}</td><td class="dns-value">${esc(record.data?dnsRecordValue(record):record.content)}</td><td>${record.proxied?'Proxied':'DNS only'}</td><td><div class="row-actions">${['A','AAAA','CNAME','MX','TXT','SRV'].includes(record.type)?`<button class="button small" data-hosting="dns-update" data-id="${esc(record.id)}">Edit</button>`:''}<button class="icon-button" data-hosting="dns-delete" data-id="${esc(record.id)}" aria-label="Delete ${esc(record.type)} record ${esc(record.name)}">${icon('close')}</button></div></td></tr>`).join('')||emptyRow(5,'No records')}</tbody></table></div><div class="table-footer"><span>${dns.page} / ${Math.max(1,dns.pages)}</span><div class="row-actions"><button class="button small" data-hosting="dns-prev" ${dns.page>1?'':'disabled'}>Previous</button><button class="button small" data-hosting="dns-next" ${dns.page<dns.pages?'':'disabled'}>Next</button><button class="button small" data-hosting="dns-disconnect">Disconnect</button></div></div></article>`}`;}
async function loadDNS(){if(dnsLoading)return;const owner=selectedOwner();if(!owner)return;const names=state.domains.owned.map(row=>row.name);if(!names.includes(state.dns.domain))state.dns={domain:names[0]||'',connected:false,records:[],page:1,pages:1};if(!state.dns.domain)return;const allocation=state.domains.owned.find(row=>row.name===state.dns.domain);if((allocation?.dnsProvider||'external')!=='cloudflare'){Object.assign(state.dns,{connected:false,records:[],error:'',page:1,pages:1});return;}dnsLoading=true;const domain=state.dns.domain,page=state.dns.page;try{const query=`owner=${encodeURIComponent(owner)}&domain=${encodeURIComponent(domain)}`,status=await api(`dns/status?${query}`);if(selectedOwner()!==owner||state.dns.domain!==domain)return;Object.assign(state.dns,status,{error:'',records:[]});if(status.connected){const records=await api(`dns/records?${query}&page=${page}`);if(selectedOwner()===owner&&state.dns.domain===domain)Object.assign(state.dns,records);}}catch(error){if(selectedOwner()===owner&&state.dns.domain===domain)state.dns.error=error.message;}finally{dnsLoading=false;}}
function hostingDialog(action,button){const dns=state.dns,mail=state.mail;const hidden=(name,value)=>`<input type="hidden" name="${name}" value="${esc(value)}">`;let title='',fields='',confirmation='',submit='Save';
 if(action==='mail-choice'){title=mail.enabled?'Disable email hosting?':'Enable email hosting?';fields=hidden('enabled',!mail.enabled);if(mail.enabled)confirmation='Mailbox data will be retained.';}
 if(action==='mail-create'||action==='mail-password'){title=action==='mail-create'?'Create mailbox':'Change password';fields=action==='mail-create'?`<label>Mailbox<input name="local" pattern="[a-z0-9][a-z0-9_-]{0,31}" maxlength="32" required></label><label>Domain<select name="domain">${mail.domains.map(domain=>`<option>${esc(domain)}</option>`).join('')}</select></label>`:hidden('local',button.dataset.local)+hidden('domain',button.dataset.domain);fields+='<label>Password<input type="password" name="password" minlength="16" maxlength="128" autocomplete="new-password" required></label>';}
 if(action==='mail-toggle'){title=button.dataset.enabled==='true'?'Enable mailbox?':'Disable mailbox?';fields=hidden('domain',button.dataset.domain)+hidden('local',button.dataset.local)+hidden('enabled',button.dataset.enabled);}
 if(action==='dns-connect'){title='Cloudflare connection';fields=hidden('domain',dns.domain)+'<label>Zone ID<input name="zone" pattern="[0-9a-f]{32}" maxlength="32" required spellcheck="false"></label><label>API token<input type="password" name="token" minlength="20" maxlength="256" autocomplete="off" required></label>';submit='Connect';}
 if(action==='dns-create'||action==='dns-update'){const record=action==='dns-update'?dns.records.find(row=>row.id===button.dataset.id):{type:'A',name:dns.domain,content:'',ttl:1,proxied:false};title=action==='dns-create'?'Add DNS record':'Edit DNS record';fields=hidden('domain',dns.domain)+(record.id?hidden('id',record.id):'')+`<label>Type<select name="type">${['A','AAAA','CNAME','MX','TXT','SRV'].map(type=>`<option ${type===record.type?'selected':''}>${type}</option>`).join('')}</select></label><label>Name<input name="name" value="${esc(record.name)}" maxlength="253" required spellcheck="false"></label><label>Content / SRV target<input name="content" value="${esc(record.data?.target||record.content)}" maxlength="2048" required></label><div class="form-columns"><label>TTL<input name="ttl" type="number" min="1" max="86400" value="${record.ttl}" required></label><label>Priority<input name="priority" type="number" min="0" max="65535" value="${record.data?.priority??record.priority??10}"></label><label>SRV port<input name="port" type="number" min="1" max="65535" value="${record.data?.port??993}"></label><label>SRV weight<input name="weight" type="number" min="0" max="65535" value="${record.data?.weight??1}"></label></div><label>Proxy<select name="proxied"><option value="false" ${record.proxied?'':'selected'}>DNS only</option><option value="true" ${record.proxied?'selected':''}>Proxied</option></select></label>`;submit='Publish';}
 if(action==='dns-delete'){const record=dns.records.find(row=>row.id===button.dataset.id);title='Delete DNS record?';confirmation=`${esc(record.type)} · ${esc(record.name)}`;fields=hidden('domain',dns.domain)+hidden('id',record.id);submit='Delete';}
 if(action==='dns-disconnect'){title='Disconnect Cloudflare?';fields=hidden('domain',dns.domain);submit='Disconnect';}
 showDialog(`<h2 id="dialog-title">${title}</h2>${confirmation?`<p>${confirmation}</p>`:''}<form data-hosting-form="${action}">${fields}<p class="login-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button type="submit" class="button primary">${submit}</button></div></form>`);
}
document.addEventListener('change',async event=>{if(event.target.id!=='dns-provider')return;const provider=event.target.value;event.target.disabled=true;try{await api('dns/provider',{owner:selectedOwner(),domain:state.dns.domain,provider});state.dns={domain:state.dns.domain,connected:false,records:[],page:1,pages:1};await loadTenant();renderContent();}catch(error){toast(error.message,true);event.target.disabled=false;}});
document.addEventListener('click',async event=>{const tool=event.target.closest('[data-db-tool]');if(tool){if(state.session.demo){toast('Unavailable in demonstration',true);return;}if(!isOwner()){toast('Site owner sign-in required',true);return;}window.open(tool.dataset.dbTool==='roundcube'?state.tools.roundcube:tool.dataset.dbTool==='mariadb'?state.tools.phpmyadmin:state.tools.pgadmin,'_blank','noopener,noreferrer');return;}const button=event.target.closest('[data-mail-security]');if(!button||button.disabled)return;const domain=domainMail(button.dataset.domain),action=button.dataset.mailSecurity;let title='',fields='',submit='Save';const hidden=`<input type="hidden" name="domain" value="${esc(domain.domain)}">`;
 if(action==='records'){showDialog(`<h2 id="dialog-title">DNS records</h2><div class="record-dialog">${mailRecordTable(domain)}</div><div class="dialog-actions"><button class="button primary" data-action="close-dialog">Close</button></div>`);$('#dialog').classList.add('wide-dialog');return;}$('#dialog').classList.remove('wide-dialog');
 if(action==='generate'){title=domain.activeSelector?'Rotate DKIM key?':'Generate DKIM key?';submit='Generate';}
 if(action==='activate'){title='Activate DKIM';fields=`<label>Selector<select name="selector">${Object.keys(domain.selectors||{}).map(selector=>`<option ${selector===(domain.pendingSelector||domain.activeSelector)?'selected':''}>${esc(selector)}</option>`).join('')}</select></label><label class="checkbox-label"><input type="checkbox" name="published" value="true" required>DNS record published</label>`;submit='Activate';}
 if(action==='disable'){title='Disable DKIM?';submit='Disable';}
 if(action==='discovery'){title=domain.discoveryEnabled?'Disable autodiscovery?':'Enable autodiscovery?';fields=`<input type="hidden" name="enabled" value="${!domain.discoveryEnabled}">`;}
 showDialog(`<h2 id="dialog-title">${title}</h2><form data-mail-security-form="${action}">${hidden}${fields}<p class="login-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button type="submit" class="button primary">${submit}</button></div></form>`);
});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.mailSecurityForm)return;event.preventDefault();const action=form.dataset.mailSecurityForm,data=Object.fromEntries(new FormData(form));data.owner=selectedOwner();if('enabled'in data)data.enabled=data.enabled==='true';if('published'in data)data.published=data.published==='true';const submit=$('button[type=submit]',form);submit.disabled=true;try{await api(action==='discovery'?'mail/discovery':`mail/dkim.${action}`,data);closeDialog();toast('Saved');await refresh();}catch(error){$('.login-error',form).textContent=error.message;submit.disabled=false;}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-mail-record]');if(!button)return;const domain=domainMail(button.dataset.domain),record=domain?.records[Number(button.dataset.index)];if(!record)return;try{if(button.dataset.mailRecord==='copy'){await navigator.clipboard.writeText(dnsZoneRecord(record));toast('Copied');}else{showDialog(`<h2 id="dialog-title">Publish DNS record?</h2>${facts([['Domain',domain.domain],['Type',record.type],['Name',record.name]])}<form data-mail-record-form><input type="hidden" name="domain" value="${esc(domain.domain)}"><input type="hidden" name="index" value="${button.dataset.index}"><p class="login-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button type="submit" class="button primary">Publish</button></div></form>`);}}catch(error){toast(error.message,true);}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.hasAttribute('data-mail-record-form'))return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),record=domainMail(data.domain)?.records[Number(data.index)];if(!record)return;const submit=$('button[type=submit]',form);submit.disabled=true;try{await api('dns/create',{owner:selectedOwner(),domain:data.domain,record});closeDialog();toast('Published');}catch(error){$('.login-error',form).textContent=error.message;submit.disabled=false;}});
$('#dialog').addEventListener('close',()=>{$('#dialog').classList.remove('wide-dialog');});

async function loadSpam(){const owner=selectedOwner();if(!owner)return;state.spam.messages=[];state.spam.error='';const result=await api(`spam/policy?owner=${encodeURIComponent(owner)}`);if(owner!==selectedOwner())return;Object.assign(state.spam,result);const boxes=state.mail.mailboxes.filter(box=>box.enabled).map(box=>box.address);if(!boxes.includes(state.spam.mailbox))state.spam.mailbox=state.mail.defaultMailbox||boxes[0]||'';if(state.mail.enabled&&state.spam.mailbox){try{const data=await api(`quarantine?owner=${encodeURIComponent(owner)}&mailbox=${encodeURIComponent(state.spam.mailbox)}`);if(owner===selectedOwner())state.spam.messages=data.messages;}catch(error){state.spam.error=error.message;}}}
function spamView(){const spam=state.spam;return `${ownerPicker()}<div class="detail-grid"><article class="card detail-card"><h2>Filtering</h2>${facts([['Junk score',spam.server.junkScore],['Reject score',spam.server.rejectScore],['Server blocklist',spam.server.blocked.length+' '+(spam.server.blocked.length===1?'rule':'rules')]])}${!isOwner()?'<button class="button" data-spam-admin>Server policy</button>':''}</article><article class="card detail-card"><h2>Sender rules</h2>${facts([['Allowed',spam.policy.allowed.length],['Blocked',spam.policy.blocked.length]])}<button class="button" data-spam-rules ${state.mail.enabled?'':'disabled'}>Edit rules</button></article></div><div class="section-toolbar"><label for="quarantine-mailbox">Mailbox</label><select id="quarantine-mailbox" ${state.mail.enabled?'':'disabled'}>${state.mail.mailboxes.filter(box=>box.enabled).map(box=>`<option ${box.address===spam.mailbox?'selected':''}>${esc(box.address)}</option>`).join('')}</select></div>${spam.error?`<div class="connection-error" role="alert">${esc(spam.error)}</div>`:''}<article class="card"><div class="card-header"><h2>Junk review</h2><span class="muted">${spam.messages.length} ${spam.messages.length===1?'message':'messages'}</span></div><div class="table-wrap"><table><thead><tr><th>Sender</th><th>Subject</th><th>Received</th><th>Actions</th></tr></thead><tbody>${spam.messages.map((row,index)=>`<tr><td>${esc(row['hdr.from'])}</td><td>${esc(row['hdr.subject']||'(No subject)')}</td><td>${esc(row['date.received'])}</td><td><div class="row-actions">${[['release','Release'],['reject','Reject'],['allow','Allow sender'],['block','Block sender']].map(([action,label])=>`<button class="button small" data-quarantine="${action}" data-index="${index}">${label}</button>`).join('')}</div></td></tr>`).join('')||emptyRow(4,state.mail.enabled?'No messages':'Local email disabled')}</tbody></table></div></article>`;}
function ruleLines(values){return esc(values.join('\n'));}
document.addEventListener('click',async event=>{const admin=event.target.closest('[data-spam-admin]'),rules=event.target.closest('[data-spam-rules]'),main=event.target.closest('[data-mail-primary]');if(admin||rules){const policy=admin?state.spam.server:state.spam.policy;showDialog(`<h2 id="dialog-title">${admin?'Server spam policy':'Sender rules'}</h2><form data-spam-form="${admin?'admin':'owner'}">${admin?`<label>Junk score<input name="junkScore" type="number" min="1" max="99" step="0.1" value="${policy.junkScore}" required></label><label>Reject score<input name="rejectScore" type="number" min="1" max="100" step="0.1" value="${policy.rejectScore}" required></label>`:`<label>Allowed senders<textarea name="allowed" rows="5" placeholder="sender@example.com or @example.com">${ruleLines(policy.allowed)}</textarea></label>`}<label>Blocked senders<textarea name="blocked" rows="5" placeholder="sender@example.com or @example.com">${ruleLines(policy.blocked)}</textarea></label><p role="alert" class="login-error"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button class="button primary" type="submit">Save</button></div></form>`);return;}if(main){showDialog(`<h2 id="dialog-title">Main email domain</h2><form data-mail-primary-form><label>Domain<select name="domain">${state.mail.domains.map(domain=>`<option ${domain===state.mail.mainDomain?'selected':''}>${esc(domain)}</option>`).join('')}</select></label><p class="login-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button class="button primary" type="submit">Save</button></div></form>`);return;}const button=event.target.closest('[data-quarantine]');if(!button)return;const row=state.spam.messages[Number(button.dataset.index)],action=button.dataset.quarantine;if(!row)return;if(action==='allow'||action==='block'){const raw=row['hdr.from']||'',sender=raw.match(/<([^>]+)>/)?.[1]||raw;const policy=structuredClone(state.spam.policy),key=action==='allow'?'allowed':'blocked';if(!policy[key].includes(sender))policy[key].push(sender);button.disabled=true;try{await api('spam/policy',{owner:selectedOwner(),policy});await loadSpam();renderContent();toast('Saved');}catch(error){toast(error.message,true);button.disabled=false;}return;}showDialog(`<h2 id="dialog-title">${action==='release'?'Release message?':'Reject message?'}</h2>${facts([['Sender',row['hdr.from']],['Subject',row['hdr.subject']],['Destination',action==='release'?'Inbox':'Trash']])}<form data-quarantine-form="${action}"><input type="hidden" name="guid" value="${esc(row.guid)}"><p class="login-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button class="button primary" type="submit">${action==='release'?'Release':'Reject'}</button></div></form>`);});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.hasAttribute('data-spam-form')&&!form.hasAttribute('data-quarantine-form')&&!form.hasAttribute('data-mail-primary-form'))return;event.preventDefault();const values=Object.fromEntries(new FormData(form)),submit=$('button[type=submit]',form);submit.disabled=true;try{if(form.hasAttribute('data-spam-form')){const admin=form.dataset.spamForm==='admin',policy={blocked:values.blocked.split(/\r?\n/).map(value=>value.trim()).filter(Boolean)};if(admin){policy.junkScore=Number(values.junkScore);policy.rejectScore=Number(values.rejectScore);}else policy.allowed=values.allowed.split(/\r?\n/).map(value=>value.trim()).filter(Boolean);await api(admin?'spam/admin':'spam/policy',{owner:selectedOwner(),policy});}else if(form.hasAttribute('data-mail-primary-form'))await api('mail/primary',{owner:selectedOwner(),domain:values.domain});else await api('quarantine/'+form.dataset.quarantineForm,{owner:selectedOwner(),mailbox:state.spam.mailbox,guid:values.guid});closeDialog();await refresh();toast('Saved');}catch(error){$('.login-error',form).textContent=error.message;submit.disabled=false;}});
document.addEventListener('change',async event=>{if(event.target.id==='quarantine-mailbox'){state.spam.mailbox=event.target.value;await loadSpam();renderContent();}});
window.addEventListener('hashchange',async()=>{if(state.view==='spam'){await loadSpam();if(state.view==='spam')renderContent();}});
window.addEventListener('hashchange',async()=>{if(state.view==='logs'){try{await loadSiteLogs();if(state.view==='logs')renderContent();}catch(error){toast(error.message,true);}}});
(async()=>{try{state.session=await api('session');state.view=location.hash.slice(1)||'overview';renderShell();await refresh();}catch(error){await syncAuthMode();renderLogin(error.message==='Sign in to continue'?'':error.message);}})();

document.addEventListener('click',event=>{const button=event.target.closest('[data-admin-db-tool]');if(!button||button.disabled)return;if(state.session?.role!=='admin')return;if(state.session.demo){toast('Unavailable in demonstration',true);return;}const url=button.dataset.adminDbTool==='mariadb'?state.tools.adminPhpmyadmin:state.tools.adminPgadmin;if(url)window.open(url,'_blank','noopener,noreferrer');});
